node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { Ledger } from './src/ledger.mjs';

const t = (id, from='a', to='b', amount=10) => ({id, from, to, amount});
const ledger = new Ledger({a: 100, b: 0});
assert.deepEqual(ledger.applyBatch([t('same'), t('same')]), {a: 90, b: 10});
assert.deepEqual(ledger.applyBatch([t('same')]), {a: 90, b: 10});
const before = ledger.snapshot();
assert.throws(() => ledger.applyBatch([t('later'), t('bad', 'a', 'b', 1000)]));
assert.deepEqual(ledger.snapshot(), before);
assert.deepEqual(ledger.applyBatch([t('later')]), {a: 80, b: 20});
assert.throws(() => ledger.applyBatch([t('same', 'a', 'b', 11)]));
assert.deepEqual(ledger.snapshot(), {a: 80, b: 20});
assert.deepEqual(ledger.applyBatch([t('self', 'a', 'a', 20)]), {a: 80, b: 20});
assert.throws(() => ledger.applyBatch([{id:'bad-account', from: 1, to: 'b', amount: 1}]));
assert.throws(() => ledger.applyBatch([{id:'bad-amount', from: 'a', to: 'b', amount: Number.MAX_SAFE_INTEGER + 1}]));
console.log('Additional batch-contract checks passed');
EOF

