patches.before:
import { applyTransfer, sameTransfer } from './transfer.mjs';
export class Ledger {
  constructor(balances) { this.balances = { ...balances }; this.committed = new Map(); }
  snapshot() { return { ...this.balances }; }
  applyBatch(transfers) {
    const balances = this.balances;
    const committed = new Map(this.committed);
    for (const transfer of transfers) {
      const previous = this.committed.get(transfer.id);
      if (previous) {
        if (!sameTransfer(previous, transfer)) throw new Error('Conflicting transfer id');
        continue;
      }
      applyTransfer(balances, transfer); committed.set(transfer.id, { ...transfer });
    }
    this.balances = balances; this.committed = committed;
    return this.snapshot();
  }
}

patches.after:
import { applyTransfer, sameTransfer } from './transfer.mjs';
export class Ledger {
  constructor(balances) { this.balances = { ...balances }; this.committed = new Map(); }
  snapshot() { return { ...this.balances }; }
  applyBatch(transfers) {
    const balances = { ...this.balances };
    const committed = new Map(this.committed);
    for (const transfer of transfers) {
      const previous = committed.get(transfer.id);
      if (committed.has(transfer.id)) {
        if (!sameTransfer(previous, transfer)) throw new Error('Conflicting transfer id');
        continue;
      }
      applyTransfer(balances, transfer);
      committed.set(transfer.id, { ...transfer });
    }
    this.balances = balances; this.committed = committed;
    return this.snapshot();
  }
}

patches.before:
export function applyTransfer(balances, transfer) {
  const { from, to, amount } = transfer;
  if (!Object.hasOwn(balances, from) || !Object.hasOwn(balances, to)) throw new Error('Unknown account');
  if (!Number.isInteger(amount) || amount <= 0) throw new Error('Invalid amount');
  if (balances[from] < amount) throw new Error('Insufficient funds');
  if (from === to) return;
  balances[from] -= amount; balances[to] += amount;
}
export function sameTransfer(a, b) { return a.from === b.from && a.to === b.to && a.amount === b.amount; }

